    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover,
a:active {
    color: var(--color-link-hover);
    text-decoration: underline;
}

a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
    border-radius: var(--radius-sm);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: var(--font-size-base);
    font-weight: 600;
    border: 2px solid transparent;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: all 0.2s ease;
    text-decoration: none;
    text-align: center;
    min-height: 44px;
    min-width: 44px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.btn:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-bg);
    border-color: var(--color-accent);
}

.btn-primary:hover,
.btn-primary:active {
    background-color: var(--color-link-hover);
    border-color: var(--color-link-hover);
}

.btn-secondary {
    background-color: transparent;
    color: var(--color-text);
    border-color: var(--color-border);
}

.btn-secondary:hover,
.btn-secondary:active {
    background-color: var(--color-surface-alt);
    border-color: var(--color-accent);
    color: var(--color-accent);
}

.btn-close {
    background: none;
    border: none;
    color: var(--color-text);
    font-size: 2rem;
    cursor: pointer;
    padding: var(--spacing-xs);
    min-height: 44px;
    min-width: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: color 0.2s ease;
}

.btn-close:hover,
.btn-close:active {
    color: var(--color-accent);
}

.btn-close:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

/* Header */
.page-header {
    background-color: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--spacing-md) 0;
}

.logo {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-text);
    transition: color 0.2s ease;
}

.logo:hover,
.logo:active {
    color: var(--color-accent);
}

.logo:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 4px;
    border-radius: var(--radius-sm);
}

.logo svg {
    fill: currentColor;
    stroke: currentColor;
}

.nav-primary ul {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-primary a {
    color: var(--color-text);
    font-weight: 500;
    transition: color 0.2s ease;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-sm);
}

.nav-primary a:hover,
.nav-primary a:active {
    color: var(--color-accent);
}

.nav-primary a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, var(--color-surface-alt) 0%, var(--color-surface) 100%);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-2xl) var(--spacing-md);
    text-align: center;
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
}

.hero h1 {
    margin-bottom: var(--spacing-md);
    font-size: clamp(var(--font-size-2xl), 5vw, var(--font-size-3xl));
}

.hero p {
    font-size: var(--font-size-lg);
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
}

.hero .btn {
    margin-top: var(--spacing-md);
}

/* Sections */
.section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

.section h2 {
    margin-bottom: var(--spacing-xs);
}

.section-description {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
    font-size: var(--font-size-lg);
}

.featured-section {
    background-color: var(--color-bg);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.product-card {
    background-color: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

@media (prefers-reduced-motion: no-preference) {
    .product-card {
        transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .product-card:hover {
        transform: translateY(-4px);
        box-shadow: 0 8px 24px rgba(88, 166, 255, 0.12);
    }
}

.product-card:focus-within {
    box-shadow: 0 0 0 2px var(--color-focus);
}

.product-link {
    display: block;
    text-decoration: none;
    flex: 1;
    display: flex;
    flex-direction: column;
    padding: var(--spacing-md);
}

.product-link:focus {
    outline: none;
}

.product-link h3 {
    color: var(--color-link);
    margin-top: var(--spacing-md);
}

.product-link:hover h3,
.product-link:active h3 {
    color: var(--color-link-hover);
}

.product-image-wrapper {
    width: 100%;
    height: 200px;
    background-color: var(--color-surface-alt);
    border-radius: var(--radius-md);
    overflow: hidden;
    margin-bottom: var(--spacing-md);
}

.product-image-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-card .price {
    font-size: var(--font-size-lg);
    font-weight: 600;
    color: var(--color-accent);
    margin-bottom: var(--spacing-md);
}

.product-card .btn {
    margin-top: auto;
    width: 100%;
    padding: var(--spacing-sm);
}

/* Deals Section */
.deals-section {
    background: linear-gradient(135deg, var(--color-surface) 0%, var(--color-surface-alt) 100%);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    position: relative;
    overflow: hidden;
}

.deal-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--color-accent), var(--color-link));
}

.deal-badge {
    display: inline-block;
    background-color: var(--color-accent-dark);
    color: var(--color-bg);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: var(--font-size-sm);
    margin-bottom: var(--spacing-md);
}

.deal-card h3 {
    margin-bottom: var(--spacing-xs);
}

.deal-card p {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-md);
}

.link-arrow {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
    font-weight: 600;
    padding: var(--spacing-xs) 0;
}

/* Editorial Section */
.editorial-section {
    background-color: var(--color-bg);
}

.articles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--spacing-lg);
}

.article-card {
    background-color: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

@media (prefers-reduced-motion: no-preference) {
    .article-card {
        transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .article-card:hover {
        transform: translateY(-4px);
        box-shadow: 0 8px 24px rgba(88, 166, 255, 0.12);
    }
}

.article-image {
    width: 100%;
    height: 200px;
    overflow: hidden;
    background-color: var(--color-surface-alt);
}

.article-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.article-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
}

.article-category {
    display: inline-block;
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-accent);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--spacing-sm);
    width: fit-content;
}

.article-card h3 {
    margin-bottom: var(--spacing-sm);
    line-height: 1.4;
}

.article-card h3 a {
    color: var(--color-text);
}

.article-card h3 a:hover,
.article-card h3 a:active {
    color: var(--color-accent);
}

.article-card h3 a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.article-card p {
    color: var(--color-text-muted);
    font-size: var(--font-size-sm);
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.article-card time {
    font-size: var(--font-size-sm);
    color: var(--color-text-muted);
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-surface) 0%, var(--color-surface-alt) 100%);
    text-align: center;
}

.newsletter-section h2 {
    margin-bottom: var(--spacing-md);
}

.newsletter-section p {
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-lg);
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    max-width: 500px;
    margin: 0 auto var(--spacing-md);
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 200px;
    padding: var(--spacing-sm) var(--spacing-md);
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    color: var(--color-text);
    font-size: var(--font-size-base);
    transition: border-color 0.2s ease;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--color-focus);
    box-shadow: 0 0 0 2px rgba(88, 166, 255, 0.2);
}

.newsletter-form input::placeholder {
    color: var(--color-text-muted);
}

.form-message {
    min-height: 1.5rem;
    color: var(--color-text-muted);
    font-size: var(--font-size-sm);
}

.form-message.success {
    color: var(--color-success);
}

.form-message.error {
    color: var(--color-danger);
}

/* Footer */
.page-footer {
    background-color: var(--color-surface);
    border-top: 1px solid var(--color-border);
    padding: var(--spacing-2xl) var(--spacing-md) var(--spacing-lg);
    margin-top: var(--spacing-2xl);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
}

.footer-section h3 {
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-lg);
}

.footer-section nav ul {
    list-style: none;
}

.footer-section nav li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-muted);
    font-size: var(--font-size-sm);
    transition: color 0.2s ease;
}

.footer-section a:hover,
.footer-section a:active {
    color: var(--color-accent);
}

.footer-section a:focus {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
    border-radius: var(--radius-sm);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    color: var(--color-text-muted);
    font-size: var(--font-size-sm);
}

/* Cart Sidebar */
.cart-sidebar {
    position: fixed;
    right: 0;
    top: 0;
    width: min(90vw, 400px);
    height: 100vh;
    background-color: var(--color-surface);
    border-left: 1px solid var(--color-border);
    z-index: 200;
    display: flex;
    flex-direction: column;
    animation: slideIn 0.3s ease;
}

@media (prefers-reduced-motion: reduce) {
    .cart-sidebar {
        animation: none;
    }
}

@media (prefers-reduced-motion: no-preference) {
    @keyframes slideIn {
        from {
            transform: translateX(100%);
        }
        to {
            transform: translateX(0);
        }
    }
}

.cart-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--spacing-lg);
    border-bottom: 1px solid var(--color-border);
}

.cart-header h2 {
    margin: 0;
}

.cart-body {
    flex: 1;
    padding: var(--spacing-lg);
    overflow-y: auto;
}

.empty-message {
    color: var(--color-text-muted);
    text-align: center;
    padding: var(--spacing-lg) 0;
}

.cart-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.6);
    z-index: 150;
    animation: fadeIn 0.2s ease;
}

@media (prefers-reduced-motion: reduce) {
    .cart-overlay {
        animation: none;
    }
}

@media (prefers-reduced-motion: no-preference) {
    @keyframes fadeIn {
        from {
            opacity: 0;
        }
        to {
            opacity: 1;
        }
    }
}

/* Responsive Design */
@media (max-width: 768px) {
    .header-top {
        flex-direction: column;
        gap: var(--spacing-md);
        padding: var(--spacing-md) 0;
    }

    .nav-primary ul {
        flex-wrap: wrap;
        justify-content: center;
        gap: var(--spacing-md);
    }

    .hero {
        padding: var(--spacing-xl) var(--spacing-md);
    }

    .hero h1 {
        font-size: var(--font-size-2xl);
    }

    .section {
        padding: var(--spacing-xl) var(--spacing-md);
    }

    .product-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-form .btn {
        width: 100%;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-lg: 1.5rem;
        --spacing-md: 1rem;
    }

    h1 {
        font-size: var(--font-size-2xl);
    }

    h2 {
        font-size: var(--font-size-xl);
    }

    .product-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: var(--spacing-sm);
    }

    .product-card {
        border-radius: var(--radius-md);
    }

    .cart-sidebar {
        width: 100%;
    }
}

/* Forced Colors Mode */
@media (forced-colors: active) {
    .btn-primary {
        border-color: ButtonBorder;
        color: ButtonText;
    }

    .btn-secondary {
        border-color: ButtonBorder;
        color: ButtonText;
    }

    .product-card,
    .deal-card,
    .article-card {
        border: 1px solid ButtonBorder;
    }

    .page-header,
    .page-footer {
        border-color: ButtonBorder;
    }

    a:focus,
    .btn:focus,
    .logo:focus,
    .nav-primary a:focus,
    .btn-close:focus,
    .footer-section a:focus,
    .article-card h3 a:focus {
        outline: 3px solid Highlight;
        outline-offset: 2px;
    }

    input:focus {
        outline: 3px solid Highlight;
        outline-offset: 2px;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: more) {
    --color-text: #ffffff;
    --color-link: #58a6ff;
    --color-accent: #79c0ff;
    --color-border: #ffffff;
}

