const puppeteer = require('puppeteer');
const { injectAxe, checkA11y } = require('axe-puppeteer');

async function testAccessibility() {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  try {
    const page = await browser.newPage();
    const filePath = `file://${process.cwd()}/index.html`;
    await page.goto(filePath, { waitUntil: 'networkidle0' });

    // Inject axe-core
    await injectAxe(page);

    // Run accessibility check
    const results = await page.evaluate(() => {
      return new Promise((resolve) => {
        axe.run((error, results) => {
          if (error) throw error;
          resolve(results);
        });
      });
    });

    console.log('\n=== ACCESSIBILITY TEST RESULTS ===\n');
    console.log(`Total Violations: ${results.violations.length}`);
    console.log(`Total Passes: ${results.passes.length}`);
    console.log(`Total Incomplete: ${results.incomplete.length}`);

    if (results.violations.length > 0) {
      console.log('\n--- VIOLATIONS ---');
      results.violations.forEach(violation => {
        console.log(`\n❌ ${violation.id}: ${violation.impact.toUpperCase()}`);
        console.log(`   ${violation.description}`);
        console.log(`   Affected nodes: ${violation.nodes.length}`);
        violation.nodes.slice(0, 3).forEach(node => {
          console.log(`   - ${node.html.substring(0, 100)}`);
        });
      });
    }

    if (results.incomplete.length > 0) {
      console.log('\n--- MANUAL REVIEW NEEDED ---');
      results.incomplete.forEach(item => {
        console.log(`⚠️  ${item.id}: ${item.description}`);
      });
    }

    return results;
  } finally {
    await browser.close();
  }
}

testAccessibility().catch(console.error);
