<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Accessibility Test</title>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/axe-core/4.7.2/axe.min.js"></script>
</head>
<body>
    <h1>Accessibility Test Results</h1>
    <div id="results"></div>
    <script>
        function runTest() {
            // Open index.html in iframe and test it
            const resultsDiv = document.getElementById('results');
            resultsDiv.innerHTML = '<p>Testing... Please wait.</p>';

            const iframe = document.createElement('iframe');
            iframe.src = 'index.html';
            iframe.style.display = 'none';
            document.body.appendChild(iframe);

            iframe.onload = function() {
                try {
                    axe.run(iframe.contentDocument, (error, results) => {
                        if (error) {
                            resultsDiv.innerHTML = `<p>Error: ${error}</p>`;
                            return;
                        }

                        let html = '<h2>Test Results</h2>';
                        html += `<p><strong>Violations:</strong> ${results.violations.length}</p>`;
                        html += `<p><strong>Passes:</strong> ${results.passes.length}</p>`;
                        html += `<p><strong>Incomplete:</strong> ${results.incomplete.length}</p>`;

                        if (results.violations.length > 0) {
                            html += '<h3>Issues Found:</h3><ul>';
                            results.violations.forEach(v => {
                                html += `<li><strong>${v.id} (${v.impact}):</strong> ${v.description}</li>`;
                            });
                            html += '</ul>';
                        }

                        resultsDiv.innerHTML = html;
                        console.log('Full results:', results);
                    });
                } catch (e) {
                    resultsDiv.innerHTML = `<p>Error: ${e.message}</p>`;
                }
            };
        }

        runTest();
    </script>
</body>
</html>
