const fs = require('fs');
const path = require('path');

// Read the HTML file
const html = fs.readFileSync('index.html', 'utf-8');

console.log('\n=== MANUAL ACCESSIBILITY ANALYSIS ===\n');

const issues = [];

// Check 1: Form labels
const inputsWithoutLabel = html.match(/<input[^>]*>/g) || [];
inputsWithoutLabel.forEach(input => {
  if (!input.includes('aria-label') && !input.includes('id')) {
    issues.push({
      type: 'WARNING',
      code: 'FORM_LABEL',
      message: 'Input found without aria-label or id',
      element: input.substring(0, 100)
    });
  }
});

// Check 2: Images without alt
const images = html.match(/<img[^>]*>/g) || [];
images.forEach(img => {
  if (!img.includes('alt=')) {
    issues.push({
      type: 'ERROR',
      code: 'IMG_ALT',
      message: 'Image missing alt attribute',
      element: img.substring(0, 100)
    });
  }
});

// Check 3: Headings structure
const h1Count = (html.match(/<h1/g) || []).length;
const headings = html.match(/<h[1-6][^>]*>/g) || [];

if (h1Count !== 1) {
  issues.push({
    type: 'ERROR',
    code: 'H1_COUNT',
    message: `Expected exactly 1 <h1>, found ${h1Count}`,
  });
}

// Check 4: Buttons with no type
const buttons = html.match(/<button[^>]*>/g) || [];
buttons.forEach(btn => {
  if (!btn.includes('type=')) {
    issues.push({
      type: 'WARNING',
      code: 'BUTTON_TYPE',
      message: 'Button missing type attribute',
      element: btn.substring(0, 100)
    });
  }
});

// Check 5: aria-label duplicates
const ariaLabels = html.match(/aria-label="([^"]*)"/g) || [];
const labelCounts = {};
ariaLabels.forEach(label => {
  labelCounts[label] = (labelCounts[label] || 0) + 1;
});

// Check 6: Main element
if (!html.includes('id="maincontent"')) {
  issues.push({
    type: 'ERROR',
    code: 'MAIN_ID',
    message: 'Main element missing id="maincontent"',
  });
}

// Check 7: Skip link
if (!html.includes('Skip to main content')) {
  issues.push({
    type: 'ERROR',
    code: 'SKIP_LINK',
    message: 'Skip to main content link missing',
  });
}

// Check 8: Form without labels (nested inputs)
const formRegex = /<form[^>]*>([\s\S]*?)<\/form>/gi;
let match;
while ((match = formRegex.exec(html)) !== null) {
  const form = match[0];
  const inputs = form.match(/<input[^>]*>/g) || [];
  inputs.forEach(input => {
    if (!form.includes(`<label`) && !input.includes('aria-label')) {
      // This is okay if input has aria-label
      if (!input.includes('aria-label')) {
        issues.push({
          type: 'WARNING',
          code: 'FORM_INPUT_LABEL',
          message: 'Form input may need explicit label',
          element: input.substring(0, 80)
        });
      }
    }
  });
}

// Check 9: Color contrast basic check (simplified)
const styles = html.match(/<style[^>]*>([\s\S]*?)<\/style>/gi) || [];

// Check 10: Role attributes (should only be used when needed)
const badRoles = html.match(/role="button"|role="link"/gi) || [];
if (badRoles.length > 0) {
  issues.push({
    type: 'WARNING',
    code: 'UNNECESSARY_ROLES',
    message: `Found ${badRoles.length} unnecessary role attributes (buttons/links are semantic)`,
  });
}

// Check 11: Nested interactive elements
const nestedPattern = /<button[^>]*>[\s\S]*?<a[\s\S]*?<\/a>[\s\S]*?<\/button>/gi;
const nestedMatches = html.match(nestedPattern) || [];
if (nestedMatches.length > 0) {
  issues.push({
    type: 'ERROR',
    code: 'NESTED_INTERACTIVE',
    message: `Found ${nestedMatches.length} nested interactive elements (button/link)`,
  });
}

// Check 12: Aria-hidden with visible content
const ariaHidden = html.match(/aria-hidden="true"[^>]*>[^<]*[a-zA-Z]/g) || [];

// Check 13: Missing lang attribute
if (!html.includes('lang=')) {
  issues.push({
    type: 'WARNING',
    code: 'NO_LANG',
    message: 'Missing lang attribute on html element',
  });
}

// Check 14: Viewport meta tag
if (!html.includes('viewport')) {
  issues.push({
    type: 'WARNING',
    code: 'NO_VIEWPORT',
    message: 'Missing viewport meta tag for responsive design',
  });
}

// Check 15: Button aria-labels with context
const addToCartButtons = html.match(/aria-label="Add to cart[^"]*"/g) || [];
if (addToCartButtons.length === 0) {
  issues.push({
    type: 'INFO',
    code: 'NO_CONTEXT_LABELS',
    message: 'Consider adding product context to Add to cart button labels',
  });
}

// Output results
console.log(`Found ${issues.length} issues:\n`);

const byType = { ERROR: [], WARNING: [], INFO: [] };
issues.forEach(issue => {
  byType[issue.type].push(issue);
});

['ERROR', 'WARNING', 'INFO'].forEach(type => {
  if (byType[type].length > 0) {
    console.log(`\n${type}S (${byType[type].length}):`);
    byType[type].forEach(issue => {
      console.log(`  ${issue.code}: ${issue.message}`);
      if (issue.element) {
        console.log(`    ${issue.element}`);
      }
    });
  }
});

// Positive checks
console.log('\n\n=== PASSING CHECKS ===');
const passes = [];

if (h1Count === 1) passes.push('✓ Exactly one <h1>');
if (html.includes('id="maincontent"')) passes.push('✓ Main element has id="maincontent"');
if (html.includes('tabindex="-1"')) passes.push('✓ Main element has tabindex="-1"');
if (html.includes('Skip to main content')) passes.push('✓ Skip link present');
if (html.includes('lang=')) passes.push('✓ Language attribute set');
if (html.includes('viewport')) passes.push('✓ Viewport meta tag present');
if (html.includes('aria-label="Primary"')) passes.push('✓ Navigation landmarks labeled');
if (html.includes('role="status"')) passes.push('✓ Live regions for status messages');
if (html.includes('aria-live=')) passes.push('✓ ARIA live regions present');

passes.forEach(p => console.log(p));

console.log(`\nTotal passes: ${passes.length}`);
EOF
