const html = fs.readFileSync('index.html', 'utf-8');
const dom = new JSDOM(html);
const doc = dom.window.document;

console.log('\n=== COMPREHENSIVE ACCESSIBILITY AUDIT ===\n');

const audit = {
  errors: [],
  warnings: [],
  passes: []
};

// Test 1: Image alt attributes
console.log('Testing image alt attributes...');
const images = doc.querySelectorAll('img');
images.forEach((img, i) => {
  const src = img.getAttribute('src');
  const alt = img.getAttribute('alt');
  if (src && src.includes('svg') && !alt) {
    audit.errors.push(`Image ${i}: SVG without alt attribute`);
  } else if (alt === '' || alt === null) {
    if (!src.includes('placeholder') && !src.includes('data:')) {
      audit.warnings.push(`Image ${i}: Empty alt - verify if decorative: ${src.substring(0, 50)}`);
    }
  }
});
if (images.length > 0 && audit.errors.length === 0) {
  audit.passes.push(`All ${images.length} images have alt attributes`);
}

// Test 2: Heading structure
console.log('Testing heading structure...');
const headings = doc.querySelectorAll('h1, h2, h3, h4, h5, h6');
const h1s = doc.querySelectorAll('h1');
if (h1s.length !== 1) {
  audit.errors.push(`Expected 1 <h1>, found ${h1s.length}`);
} else {
  audit.passes.push('Exactly one <h1> tag');
}

let prevLevel = 0;
let skipped = false;
headings.forEach((h) => {
  const level = parseInt(h.tagName[1]);
  if (level > prevLevel + 1) {
    skipped = true;
  }
  prevLevel = level;
});
if (!skipped) {
  audit.passes.push('Heading hierarchy has no skipped levels');
} else {
  audit.warnings.push('Heading hierarchy may have skipped levels');
}

// Test 3: Form elements
console.log('Testing form accessibility...');
const inputs = doc.querySelectorAll('input[type], textarea, select');
inputs.forEach((input) => {
  const id = input.getAttribute('id');
  const ariaLabel = input.getAttribute('aria-label');
  const type = input.getAttribute('type');

  // Check if it has a label
  let hasLabel = false;
  if (id) {
    const label = doc.querySelector(`label[for="${id}"]`);
    if (label) hasLabel = true;
  }
  if (ariaLabel) hasLabel = true;

  if (!hasLabel && type !== 'hidden') {
    audit.warnings.push(`Input missing label: ${type} ${id || ''}`);
  }
});
if (inputs.length > 0) {
  audit.passes.push(`Checked ${inputs.length} form inputs for labels`);
}

// Test 4: Button labels
console.log('Testing button labels...');
const buttons = doc.querySelectorAll('button');
buttons.forEach((btn, i) => {
  const text = btn.textContent.trim();
  const ariaLabel = btn.getAttribute('aria-label');

  if (!text && !ariaLabel) {
    audit.errors.push(`Button ${i} has no label (text or aria-label)`);
  }

  if (!btn.getAttribute('type')) {
    audit.warnings.push(`Button ${i} missing type attribute`);
  }
});
audit.passes.push(`Checked ${buttons.length} buttons for labels`);

// Test 5: Links
console.log('Testing link accessibility...');
const links = doc.querySelectorAll('a');
links.forEach((link, i) => {
  const href = link.getAttribute('href');
  const text = link.textContent.trim();
  const ariaLabel = link.getAttribute('aria-label');

  if (!text && !ariaLabel) {
    audit.errors.push(`Link ${i} has no text or aria-label`);
  }

  if (href === '#' && text === '') {
    audit.errors.push(`Link ${i} is empty with href="#"`);
  }
});
audit.passes.push(`Checked ${links.length} links for text content`);

// Test 6: ARIA attributes
console.log('Testing ARIA usage...');
const ariaLabels = doc.querySelectorAll('[aria-label]');
audit.passes.push(`Found ${ariaLabels.length} elements with aria-label`);

const ariaHidden = doc.querySelectorAll('[aria-hidden="true"]');
audit.passes.push(`Found ${ariaHidden.length} aria-hidden elements`);

// Test 7: Landmarks
console.log('Testing landmarks...');
const main = doc.querySelector('main');
const header = doc.querySelector('header');
const footer = doc.querySelector('footer');
const nav = doc.querySelectorAll('nav');

if (main) {
  audit.passes.push('Main landmark found');
  if (main.id) {
    audit.passes.push(`Main has id: ${main.id}`);
  } else {
    audit.warnings.push('Main element missing id');
  }
  if (main.getAttribute('tabindex') === '-1') {
    audit.passes.push('Main has tabindex="-1"');
  }
} else {
  audit.errors.push('No main element found');
}

if (header) audit.passes.push('Header landmark found');
if (footer) audit.passes.push('Footer landmark found');
if (nav.length > 0) {
  audit.passes.push(`${nav.length} navigation landmark(s) found`);
  let unlabeled = 0;
  nav.forEach(n => {
    if (!n.getAttribute('aria-label')) unlabeled++;
  });
  if (unlabeled > 1) {
    audit.warnings.push(`${unlabeled} nav elements without aria-label (need unique names)`);
  }
}

// Test 8: Skip link
console.log('Testing skip links...');
const skipLink = doc.querySelector('a[href="#maincontent"]');
if (skipLink) {
  audit.passes.push('Skip to main content link found');
} else {
  audit.warnings.push('No skip link to main content');
}

// Test 9: Language
console.log('Testing language attributes...');
const htmlElement = doc.documentElement;
if (htmlElement.getAttribute('lang')) {
  audit.passes.push(`Language attribute set: ${htmlElement.getAttribute('lang')}`);
} else {
  audit.errors.push('Missing lang attribute on html element');
}

// Test 10: Viewport
console.log('Testing viewport meta tag...');
const viewport = doc.querySelector('meta[name="viewport"]');
if (viewport) {
  audit.passes.push('Viewport meta tag present');
} else {
  audit.errors.push('Missing viewport meta tag');
}

// Test 11: Title
console.log('Testing page title...');
const title = doc.querySelector('title');
if (title && title.textContent) {
  audit.passes.push(`Page title: "${title.textContent}"`);
} else {
  audit.errors.push('Missing or empty page title');
}

// Test 12: Unique IDs
console.log('Testing unique IDs...');
const allWithIds = doc.querySelectorAll('[id]');
const ids = new Map();
let duplicateIds = 0;
allWithIds.forEach(el => {
  const id = el.getAttribute('id');
  if (ids.has(id)) {
    duplicateIds++;
    audit.errors.push(`Duplicate ID: "${id}"`);
  }
  ids.set(id, el);
});
if (duplicateIds === 0) {
  audit.passes.push(`All ${ids.size} IDs are unique`);
}

// Output results
console.log('\n=== RESULTS ===\n');

if (audit.errors.length > 0) {
  console.log(`❌ ERRORS (${audit.errors.length}):`);
  audit.errors.forEach(e => console.log(`   ${e}`));
}

if (audit.warnings.length > 0) {
  console.log(`\n⚠️  WARNINGS (${audit.warnings.length}):`);
  audit.warnings.forEach(w => console.log(`   ${w}`));
}

console.log(`\n✅ PASSES (${audit.passes.length}):`);
audit.passes.forEach(p => console.log(`   ${p}`));

const score = ((audit.passes.length - audit.warnings.length * 0.5) / (audit.passes.length + audit.errors.length)) * 100;
console.log(`\nAccessibility Score: ${Math.round(score)}%`);
console.log(`Errors: ${audit.errors.length} | Warnings: ${audit.warnings.length}`);
EOF
